{
  "name": "Livox三维激光雷达",
  "name_en": "Livox 3D LiDAR",
  "manufacturer": "Livox",
  "description": "Livox三维激光雷达是一类用于获取空间三维点云的激光传感器，可输出点的坐标、距离/角度表示、反射率、回波信息，以及部分记录中的IMU数据。它常用于实验室中的三维扫描、机器人感知、空间测绘、目标检测和点云重建。",
  "description_en": "Livox 3D LiDAR is a laser-based spatial sensor used to acquire 3D point clouds. It can provide point coordinates, range/angle representations, reflectivity, return information, and in some recordings IMU data. In laboratories it is commonly used for 3D scanning, robotic perception, spatial mapping, object detection, and point-cloud reconstruction.",
  "actions": [
    {
      "action_name": "auto-data_type0_reader",
      "description": "读取数据类型0点数据：笛卡尔坐标X/Y/Z、反射率和回波编号。",
      "description_en": "Read type-0 point data: Cartesian X/Y/Z coordinates, reflectivity, and return number."
    },
    {
      "action_name": "auto-data_type1_reader",
      "description": "读取数据类型1点数据：距离、天顶角、方位角、反射率和回波编号。",
      "description_en": "Read type-1 point data: distance, zenith angle, azimuth angle, reflectivity, and return number."
    },
    {
      "action_name": "auto-data_type2_reader",
      "description": "读取数据类型2点数据：笛卡尔坐标X/Y/Z、反射率、回波编号和标签信息。",
      "description_en": "Read type-2 point data: Cartesian X/Y/Z coordinates, reflectivity, return number, and tag information."
    },
    {
      "action_name": "auto-data_type3_reader",
      "description": "读取数据类型3点数据：距离、天顶角、方位角、反射率、回波编号和标签信息。",
      "description_en": "Read type-3 point data: distance, zenith angle, azimuth angle, reflectivity, return number, and tag information."
    },
    {
      "action_name": "auto-data_type4_reader",
      "description": "读取数据类型4双回波点数据：两组笛卡尔坐标、反射率、回波编号和标签信息。",
      "description_en": "Read type-4 dual-return point data: two sets of Cartesian coordinates, reflectivity, return numbers, and tag information."
    },
    {
      "action_name": "auto-data_type5_reader",
      "description": "读取数据类型5双回波点数据：两组距离/角度信息、反射率、回波编号和标签信息。",
      "description_en": "Read type-5 dual-return point data: two sets of range/angle values, reflectivity, return numbers, and tag information."
    },
    {
      "action_name": "auto-data_type6_reader",
      "description": "读取数据类型6惯性测量数据：角速度和加速度。",
      "description_en": "Read type-6 inertial measurement data: angular velocity and acceleration."
    },
    {
      "action_name": "auto-lvxreader",
      "description": "读取Livox专有.lvx记录文件中的帧、数据包和点云数据。",
      "description_en": "Read frames, packets, and point-cloud data from a Livox proprietary .lvx recording file."
    },
    {
      "action_name": "auto-read_frame_header",
      "description": "读取记录数据的帧头信息。",
      "description_en": "Read the frame header information of recorded data."
    },
    {
      "action_name": "auto-read_package_header",
      "description": "读取记录数据包头信息，包括时间戳和数据类型。",
      "description_en": "Read the recorded packet header information, including timestamp and data type."
    },
    {
      "action_name": "auto-simplecloudreader",
      "description": "读取带表头的简单二进制三维点云文件。",
      "description_en": "Read a simple binary 3D point-cloud file with a header."
    }
  ],
  "tag_hints": [
    "3D LiDAR",
    "point cloud acquisition",
    "Livox .lvx format",
    "reflectivity data",
    "multi-return lidar",
    "IMU data",
    "robot perception",
    "3D mapping"
  ]
}

